// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        // Configure the log file to a helper whose AddMessage reverts.
        RevertingLog logFile = new RevertingLog();
        c.SetLogFile(address(logFile));

        // Deposit through c; observe only the revert boolean of c's entry point.
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() { ok = true; } catch { ok = false; }

        // General rule: with the configured log rejecting AddMessage, no deposit
        // may complete; the reference reverts (ok == false) for every input,
        // the buggy version (log never stored, call to empty address(0) no-ops)
        // lets the deposit succeed (ok == true) for some input.
        assertTrue(!ok);
    }
}

contract RevertingLog {
    function AddMessage(address, uint256, string calldata) external pure {
        revert();
    }
}

