pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface ILog {
    function History(uint256) external view returns (address, string memory, uint256, uint256);
}

contract InvMutTest is Test {
    C c;
    ILog log;

    function setUp() public {
        c = new C();
        log = ILog(address(new LogFile()));
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(log) && actor != address(this));
        amount = bound(amount, 0, 1e30);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.SetLogFile(address(log));
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature("Deposit()"));
        assertTrue(ok && log.History(0).Sender == actor,
            "deposit must succeed and be logged in the configured LogFile");
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint256 Val;
        uint256 Time;
    }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint256 _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

