pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    SilentLog log;

    function setUp() public {
        c = new C();
        log = new SilentLog();
        c.SetMinSum(0);
        c.Initialized();
    }

    function testFuzz_property(uint256 amount, uint256 salt) public {
        amount = bound(amount, 0, 1e30);
        // Adversarial counterparty: a caller contract with code but NO AddMessage,
        // so a stray AddMessage call to it reverts. Deterministic via salt-free deploy.
        SilentCaller caller = new SilentCaller();
        // Register the log (the deployed helper has no fallback reverting on AddMessage
        // because it *implements* AddMessage as a proper LogFile).
        vm.prank(address(caller));
        c.SetLogFile(address(log));
        vm.deal(address(caller), amount);
        bool ok;
        vm.prank(address(caller));
        try c.Deposit{value: amount}() { ok = true; } catch { ok = false; }
        // General rule: once initialized with a valid LogFile, Deposit by any party never reverts.
        assertTrue(ok);
    }
}

// A LogFile stub that accepts AddMessage (so P's Deposit succeeds).
contract SilentLog {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

// Adversarial caller: has code and NO AddMessage, so a misrouted AddMessage call to it reverts.
contract SilentCaller {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}

